SELECT ((v_revenue.value - LAG(v_revenue.value) OVER (PARTITION BY v_revenue.ticker ORDER BY v_revenue.fiscal_year)) / LAG(v_revenue.value) OVER (PARTITION BY v_revenue.ticker ORDER BY v_revenue.fiscal_year)) * 100 AS revenue_growth_percentage
FROM v_revenue
WHERE v_revenue.ticker = 'AAPL' AND v_revenue.fiscal_year IN (2024, 2025);

SELECT value / ( SELECT value FROM v_total_assets WHERE ticker = 'TSLA' AND fiscal_year = 2024 ) AS cash_ratio
FROM v_cash
WHERE ticker = 'TSLA' AND fiscal_year = 2024;

SELECT value / 1e9 AS revenue_billions 
FROM v_revenue 
WHERE ticker = 'AAPL' AND fiscal_year = 2024;

SELECT v_net_income.value 
FROM v_net_income 
WHERE v_net_income.ticker = 'TSLA' AND v_net_income.fiscal_year = 2024;

SELECT SUM(value) AS total_net_income
FROM v_net_income
WHERE ticker = 'TSLA';

SELECT ((v_revenue_2025.value - v_revenue_2024.value) / v_revenue_2024.value) * 100 AS revenue_growth_percentage
FROM v_revenue AS v_revenue_2024
JOIN v_revenue AS v_revenue_2025 ON v_revenue_2024.cik = v_revenue_2025.cik AND v_revenue_2024.ticker = 'AAPL' AND v_revenue_2024.fiscal_year = 2024 AND v_revenue_2025.fiscal_year = 2025;

